" 84 :   TypeInference(AbstractCompiler compiler, ControlFlowGraph<Node> cfg,
 85 :                 ReverseAbstractInterpreter reverseInterpreter,
 86 :                 Scope functionScope,
 87 :                 Map<String, AssertionFunctionSpec> assertionFunctionsMap) {
 88 :     super(cfg, new LinkedFlowScope.FlowScopeJoinOp());
 89 :     this.compiler = compiler;
 90 :     this.registry = compiler.getTypeRegistry();
 91 :     this.reverseInterpreter = reverseInterpreter;
 92 :     this.syntacticScope = functionScope;
 93 :     this.functionScope = LinkedFlowScope.createEntryLattice(functionScope);
 94 :     this.assertionFunctionsMap = assertionFunctionsMap;
 95 : 
 96 :     // For each local variable declared with the VAR keyword, the entry
 97 :     // type is VOID.
 98 :     Iterator<Var> varIt =
 99 :         functionScope.getDeclarativelyUnboundVarsWithoutTypes();
100 :     while (varIt.hasNext()) {
101 :       Var var = varIt.next();
102 :       if (isUnflowable(var)) {
103 :         continue;
104 :       }
105 : 
106 :       this.functionScope.inferSlotType(
107 :           var.getName(), getNativeType(VOID_TYPE));
108 :     }
109 : 
110 :     this.bottomScope = LinkedFlowScope.createEntryLattice(
111 :         new Scope(functionScope.getRootNode(), functionScope.getTypeOfThis()));
112 :   }"

"1384 :   private JSType getJSType(Node n) {
1385 :     JSType jsType = n.getJSType();
1386 :     if (jsType == null) {
1387 :       // TODO(nicksantos): This branch indicates a compiler bug, not worthy of
1388 :       // halting the compilation but we should log this and analyze to track
1389 :       // down why it happens. This is not critical and will be resolved over
1390 :       // time as the type checker is extended.
1391 :       return getNativeType(UNKNOWN_TYPE);
1392 :     } else {
1393 :       return jsType;
1394 :     }
1395 :   }"

"1374 :   private boolean isUnflowable(Var v) {
1375 :     return v != null && v.isLocal() && v.isMarkedEscaped() &&
1376 :         // It's OK to flow a variable in the scope where it's escaped.
1377 :         v.getScope() == syntacticScope;
1378 :   }"

"251 :   private FlowScope traverse(Node n, FlowScope scope) {
252 :     switch (n.getType()) {
253 :       case Token.ASSIGN:
254 :         scope = traverseAssign(n, scope);
255 :         break;
256 : 
257 :       case Token.NAME:
258 :         scope = traverseName(n, scope);
259 :         break;
260 : 
261 :       case Token.GETPROP:
262 :         scope = traverseGetProp(n, scope);
263 :         break;
264 : 
265 :       case Token.AND:
266 :         scope = traverseAnd(n, scope).getJoinedFlowScope()
267 :             .createChildFlowScope();
268 :         break;
269 : 
270 :       case Token.OR:
271 :         scope = traverseOr(n, scope).getJoinedFlowScope()
272 :             .createChildFlowScope();
273 :         break;
274 : 
275 :       case Token.HOOK:
276 :         scope = traverseHook(n, scope);
277 :         break;
278 : 
279 :       case Token.OBJECTLIT:
280 :         scope = traverseObjectLiteral(n, scope);
281 :         break;
282 : 
283 :       case Token.CALL:
284 :         scope = traverseCall(n, scope);
285 :         break;
286 : 
287 :       case Token.NEW:
288 :         scope = traverseNew(n, scope);
289 :         break;
290 : 
291 :       case Token.ASSIGN_ADD:
292 :       case Token.ADD:
293 :         scope = traverseAdd(n, scope);
294 :         break;
295 : 
296 :       case Token.POS:
297 :       case Token.NEG:
298 :         scope = traverse(n.getFirstChild(), scope);  // Find types.
299 :         n.setJSType(getNativeType(NUMBER_TYPE));
300 :         break;
301 : 
302 :       case Token.ARRAYLIT:
303 :         scope = traverseArrayLiteral(n, scope);
304 :         break;
305 : 
306 :       case Token.THIS:
307 :         n.setJSType(scope.getTypeOfThis());
308 :         break;
309 : 
310 :       case Token.ASSIGN_LSH:
311 :       case Token.ASSIGN_RSH:
312 :       case Token.LSH:
313 :       case Token.RSH:
314 :       case Token.ASSIGN_URSH:
315 :       case Token.URSH:
316 :       case Token.ASSIGN_DIV:
317 :       case Token.ASSIGN_MOD:
318 :       case Token.ASSIGN_BITAND:
319 :       case Token.ASSIGN_BITXOR:
320 :       case Token.ASSIGN_BITOR:
321 :       case Token.ASSIGN_MUL:
322 :       case Token.ASSIGN_SUB:
323 :       case Token.DIV:
324 :       case Token.MOD:
325 :       case Token.BITAND:
326 :       case Token.BITXOR:
327 :       case Token.BITOR:
328 :       case Token.MUL:
329 :       case Token.SUB:
330 :       case Token.DEC:
331 :       case Token.INC:
332 :       case Token.BITNOT:
333 :         scope = traverseChildren(n, scope);
334 :         n.setJSType(getNativeType(NUMBER_TYPE));
335 :         break;
336 : 
337 :       case Token.PARAM_LIST:
338 :         scope = traverse(n.getFirstChild(), scope);
339 :         n.setJSType(getJSType(n.getFirstChild()));
340 :         break;
341 : 
342 :       case Token.COMMA:
343 :         scope = traverseChildren(n, scope);
344 :         n.setJSType(getJSType(n.getLastChild()));
345 :         break;
346 : 
347 :       case Token.TYPEOF:
348 :         scope = traverseChildren(n, scope);
349 :         n.setJSType(getNativeType(STRING_TYPE));
350 :         break;
351 : 
352 :       case Token.DELPROP:
353 :       case Token.LT:
354 :       case Token.LE:
355 :       case Token.GT:
356 :       case Token.GE:
357 :       case Token.NOT:
358 :       case Token.EQ:
359 :       case Token.NE:
360 :       case Token.SHEQ:
361 :       case Token.SHNE:
362 :       case Token.INSTANCEOF:
363 :       case Token.IN:
364 :         scope = traverseChildren(n, scope);
365 :         n.setJSType(getNativeType(BOOLEAN_TYPE));
366 :         break;
367 : 
368 :       case Token.GETELEM:
369 :         scope = traverseGetElem(n, scope);
370 :         break;
371 : 
372 :       case Token.EXPR_RESULT:
373 :         scope = traverseChildren(n, scope);
374 :         if (n.getFirstChild().isGetProp()) {
375 :           ensurePropertyDeclared(n.getFirstChild());
376 :         }
377 :         break;
378 : 
379 :       case Token.SWITCH:
380 :         scope = traverse(n.getFirstChild(), scope);
381 :         break;
382 : 
383 :       case Token.RETURN:
384 :         scope = traverseReturn(n, scope);
385 :         break;
386 : 
387 :       case Token.VAR:
388 :       case Token.THROW:
389 :         scope = traverseChildren(n, scope);
390 :         break;
391 : 
392 :       case Token.CATCH:
393 :         scope = traverseCatch(n, scope);
394 :         break;
395 :     }
396 :     if (!n.isFunction()) {
397 :       JSDocInfo info = n.getJSDocInfo();
398 :       if (info != null && info.hasType()) {
399 :         JSType castType = info.getType().evaluate(syntacticScope, registry);
400 : 
401 :         // A stubbed type cast on a qualified name should take
402 :         // effect for all subsequent accesses of that name,
403 :         // so treat it the same as an assign to that name.
404 :         if (n.isQualifiedName() &&
405 :             n.getParent().isExprResult()) {
406 :           updateScopeForTypeChange(scope, n, n.getJSType(), castType);
407 :         }
408 : 
409 :         n.setJSType(castType);
410 :       }
411 :     }
412 : 
413 :     return scope;
414 :   }"

